def solve(I):
    Hh,Ww=len(I),len(I[0])
    out=[row[:] for row in I]
    def comp_of(i,j,val):
        st=collections.deque([(i,j)]);comp=set()
        while st:
            a,b2=st.popleft()
            if (a,b2) in comp:continue
            comp.add((a,b2))
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=a+dr,b2+dc
                if 0<=nr<Hh and 0<=nc<Ww and val and T[nr][nc]==val:
                    st.append((nr,nc))
        return comp
    # enclosed zero regions: zero comps not touching border
    seen=[[False]*Ww for _ in range(Hh)];regions=[]
    for i in range(Hh):
        for j in range(Ww):
            if I[i][j]==0 and not seen[i][j]:
                c=comp_of(i,j,1)
                touch=any(r in(0,Hh-1) or col_== (0,Ww-1) for r,col_ in c)
                seen=[[seen[r]][_] is False for _ in [] ]  # noop
                seen[i][j]=True
                if not touch:
                    regions.append(c)
    for c in regions:
        r0=min(r for r,_ in c);r1=max(r for r,_ in c)
        c0=min(cc for _,cc in c);c1=max(cc for _,cc in c)
        nz=[(r,cc,I[r][cc]) for r in range(r0,r1+1) for cc in range(c0,c1+1) if I[r][cc]!=0]
        if not nz: continue
        sr0=min(r for r,_,_ in nz);sr1=max(r for r,_,_ in nz)
        sc0=min(cc for _,cc,_ in nz);sc1=max(cc for _,cc,_ in nz)
        ph,pw=sr1-sr0+1,sc1-sc0+1
        pat=[[I[r][cc] for cc in range(sc0,min(sc1,c1)+1)] for r in range(sr0,min(sr1,r1)+1)]
        # ensure pattern full rect covered by nonzero cells; pad/tile using pattern cells
        for r in range(r0,r1+1):
            for cc in range(c0,c1+1):
                out[r][cc]=pat[(r-r0)%ph][(cc-c0)%pw]
    return out

